import { answer, python, sql } from '../helpers.js';

// Les références sont celles des sujets 21-NSIJ1G11 et 21-NSIJ1AN1.
function a(question, title, prompt, value, hints, resolution, writingPrompt) {
  return answer(title, prompt, value, hints, resolution, {
    question, guidance: hints[0], pitfall: hints[1], ...(writingPrompt ? { writingPrompt } : {})
  });
}
function p(question, title, prompt, name, parameters, body, cases, hints, resolution, prefix = '', suffix = '') {
  const signature = `def ${name}(${parameters}):\n`;
  return python(title, prompt, suffix ? 'verifier' : name,
    prefix + signature + '    pass\n' + suffix,
    prefix + signature + body + '\n' + suffix, cases, hints, resolution,
    { question, guidance: hints[0], pitfall: hints[1] });
}
function s(question, title, prompt, setup, solution, expected, hints, resolution, extras = {}) {
  return sql(title, prompt, setup, solution, expected, hints, resolution,
    { question, guidance: hints[0], pitfall: hints[1], ...extras });
}
