const cesar = `class CodeCesar:
    def __init__(self, cle):
        self.cle = cle
        self.alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    def decale(self, lettre):
        num2 = self.alphabet.find(lettre) + self.cle
        if num2 >= 26: num2 -= 26
        if num2 < 0: num2 += 26
        return self.alphabet[num2]
`;
